func prepareSimplesNacionalTotals(doc *NFe) {
	doc.InfNFe.Emit.CRT = "1"
	doc.InfNFe.Det[0].Prod.CAtivSN = "01"
	doc.InfNFe.Det[0].Imposto.IBSCBS.GTribSN = &GTribSN{
		GIBSSN: &GIBSSN{PIBSSN: NewDecimal("0.10"), VIBSSN: NewDecimal("0.10")},
		GCBSSN: &GCBSSN{PCBSSN: NewDecimal("0.90"), VCBSSN: NewDecimal("0.90")},
	}
	doc.InfNFe.Total.IBSCBSTot.GTribSN = &GTribSNTot{VIBSSN: NewDecimal("0.10"), VCBSSN: NewDecimal("0.90")}
}

func requireRejection(t *testing.T, doc *NFe, code string) {
	t.Helper()
	err := doc.Validate()
	if err == nil || !strings.Contains(err.Error(), code) {
		t.Fatalf("esperava rejeição %s, obteve %v", code, err)
	}
}

func TestNFe_NT2026005_RegrasDeTotalizacao(t *testing.T) {
	valid := createValidMockNFe()
	prepareSimplesNacionalTotals(valid)
	if err := valid.Validate(); err != nil {
		t.Fatalf("totais do Simples Nacional válidos: %v", err)
	}

	missingTotal := createValidMockNFe()
	prepareSimplesNacionalTotals(missingTotal)
	missingTotal.InfNFe.Total.IBSCBSTot.GTribSN = nil
	requireRejection(t, missingTotal, "1275")

	unexpectedTotal := createValidMockNFe()
	unexpectedTotal.InfNFe.Total.IBSCBSTot.GTribSN = &GTribSNTot{VIBSSN: NewDecimal("0.00"), VCBSSN: NewDecimal("0.00")}
	requireRejection(t, unexpectedTotal, "1276")

	wrongIBS := createValidMockNFe()
	prepareSimplesNacionalTotals(wrongIBS)
	wrongIBS.InfNFe.Total.IBSCBSTot.GTribSN.VIBSSN = NewDecimal("0.11")
	requireRejection(t, wrongIBS, "1277")

	wrongCBS := createValidMockNFe()
	prepareSimplesNacionalTotals(wrongCBS)
	wrongCBS.InfNFe.Total.IBSCBSTot.GTribSN.VCBSSN = NewDecimal("0.91")
	requireRejection(t, wrongCBS, "1284")
}

